// Definition for a binary tree node.
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int val) { this.val = val; }
}

public int maxDepth(TreeNode root) {
    if (root == null) return 0;                         // empty subtree
    int leftDepth = maxDepth(root.left);                // children report first
    int rightDepth = maxDepth(root.right);
    return 1 + Math.max(leftDepth, rightDepth);         // parent combines
}

public int maxDepth(TreeNode root) {
    if (root == null) return 0;
    Queue<TreeNode> queue = new LinkedList<>();
    queue.offer(root);
    int depth = 0;
    while (!queue.isEmpty()) {
        int levelSize = queue.size();        // snapshot this level's count
        for (int i = 0; i < levelSize; i++) {
            TreeNode node = queue.poll();
            if (node.left != null) queue.offer(node.left);
            if (node.right != null) queue.offer(node.right);
        }
        depth++;                             // one full level processed
    }
    return depth;
}

